import React, { useState, useEffect } from 'react';
import './App.css';
import Dashboard from './components/Dashboard';
import Settings from './components/Settings';
import CommandHistory from './components/CommandHistory';
import Logs from './components/Logs';

function App() {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [jarvisStatus, setJarvisStatus] = useState('unknown');
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    checkJarvisStatus();
    // Check status every 3 seconds
    const interval = setInterval(checkJarvisStatus, 3000);
    return () => clearInterval(interval);
  }, []);

  const checkJarvisStatus = async () => {
    try {
      const status = await window.electronAPI.getJarvisStatus();
      setJarvisStatus(status.status || 'unknown');
      setLoading(false);
    } catch (error) {
      console.error('Error checking status:', error);
      setJarvisStatus('error');
      setLoading(false);
    }
  };

  const handleToggleJarvis = async () => {
    setLoading(true);
    try {
      if (jarvisStatus === 'running') {
        await window.electronAPI.stopJarvis();
      } else {
        await window.electronAPI.startJarvis();
      }
      // Wait a moment for process to start/stop
      setTimeout(checkJarvisStatus, 1000);
    } catch (error) {
      console.error('Error toggling JARVIS:', error);
    }
  };

  return (
    <div className="app">
      {/* Header */}
      <header className="header">
        <div className="header-left">
          <h1>🤖 JARVIS</h1>
          <p className="subtitle">AI Assistant Control Panel</p>
        </div>
        <div className="header-right">
          <div className={`status-badge ${jarvisStatus}`}>
            {jarvisStatus === 'running' && <span className="status-dot running"></span>}
            {jarvisStatus === 'stopped' && <span className="status-dot stopped"></span>}
            {jarvisStatus === 'error' && <span className="status-dot error"></span>}
            {jarvisStatus === 'unknown' && <span className="status-dot unknown"></span>}
            <span className="status-text">
              {jarvisStatus === 'running' && 'Online'}
              {jarvisStatus === 'stopped' && 'Offline'}
              {jarvisStatus === 'error' && 'Error'}
              {jarvisStatus === 'unknown' && 'Checking...'}
            </span>
          </div>
          <button
            className={`toggle-btn ${jarvisStatus === 'running' ? 'running' : 'stopped'}`}
            onClick={handleToggleJarvis}
            disabled={loading}
          >
            {loading ? '...' : jarvisStatus === 'running' ? 'Stop' : 'Start'}
          </button>
        </div>
      </header>

      {/* Navigation Tabs */}
      <nav className="nav-tabs">
        <button
          className={`nav-tab ${activeTab === 'dashboard' ? 'active' : ''}`}
          onClick={() => setActiveTab('dashboard')}
        >
          📊 Dashboard
        </button>
        <button
          className={`nav-tab ${activeTab === 'history' ? 'active' : ''}`}
          onClick={() => setActiveTab('history')}
        >
          📝 Command History
        </button>
        <button
          className={`nav-tab ${activeTab === 'logs' ? 'active' : ''}`}
          onClick={() => setActiveTab('logs')}
        >
          📋 Logs
        </button>
        <button
          className={`nav-tab ${activeTab === 'settings' ? 'active' : ''}`}
          onClick={() => setActiveTab('settings')}
        >
          ⚙️ Settings
        </button>
      </nav>

      {/* Content Area */}
      <main className="content">
        {activeTab === 'dashboard' && <Dashboard status={jarvisStatus} />}
        {activeTab === 'history' && <CommandHistory />}
        {activeTab === 'logs' && <Logs />}
        {activeTab === 'settings' && <Settings />}
      </main>

      {/* Footer */}
      <footer className="footer">
        <p>JARVIS v1.0 • AI Assistant for macOS</p>
        <p className="footer-right">Built with ❤️ by Ruthish</p>
      </footer>
    </div>
  );
}

export default App;
